import org.jsoup.nodes.Element
import org.jsoup.select.Elements

import java.text.SimpleDateFormat

class BankTransactionUtil {

    private static final log = LogFactory.getLog(this)
    private static
    final String DATE_REGEX = "(^[0-3]?[0-9][-|/|\\s*][A-z]{3,4}[-|/|\\s*][0-9]{2,4}\$)|(^[0-3]?[0-9][-|/|\\s*][0-1]?[0-9][-|/|\\s*][0-9]{2,4}\$)|(^[0-3]?[0-9][-|/|\\s*][0-1][0-9][-|/|\\s*][0-9]{2,4} [0-9]{2}:[0-9]{2}\$)"

//TODO : to change to lower case
    public static Map<String, String> headerDictionary() {
        Map<String, String> headerMap = [:]
        headerMap.put("date", "(TRAN[\\s]*DT)|(Trans.[\\s]*Date)|(^n[\\s]*Date\$)|(TXN[\\s]*DATE)|(Date[\\s]*Txn)|(Transaction[\\s]*Date)|(Txn[.][\\s]*Date)|(Txn Date)|(Txn\$)|(Tran[\\s]*[Dd]ate)|(^DATE\$)|(^Transactio\$)|(^Date\$)|(Post Date)|(TRAN DATE)|(Post)|(Txn Posted Date)|(TDATE)|(^Transaction\$)|(DATE[.])|(Txn[.][\\s]*Date)")
        headerMap.put("value_date", "(Value Date)|(Value)|(VALUE DATE)")
        headerMap.put("description", "(DESCRIPTION)|(Transaction Details)|(Transaction Particulars)|(Transaction Remarks)|(Description)|(Particulars)|(PARTICULARS)|(Transaction\$)|(Narration)|(^Transactio\$)|(^Account\$)|(NARATION)|(Details)|(Remarks)|(Description\\\\(Remark\\\\))|(DESCRIP)|(Particular)|(DESCRIPION)|(TRANSACTION[\\s]*DETAILS)|(TRANSACTION[\\s]*DETAILS)")
        headerMap.put("branch_code", "(Branch Code)|(Branch)|(Location)|(Branch[\\s]*Name)")
        headerMap.put("cheque_no", "(REFERENCE)|(Ref No./Cheque)|(Ref)|(Chq.No.)|(Chq./Ref.No.)|(Cheque)|(Cheque Number)|(Cheque No)|(ChequeN[\\s]*o[\\s]*.)|(Cheque No.)|(Chq No)|(CHQ NO)|(Chq.No)|(CHEQUE[\\s]*NO[.])|(Chq[\\s]*no[.])|(Cheque[\\s]*Num)|(CHQ[.]NO[.])")
        headerMap.put("credit", "(CREDITS)|(Credit Amt)|(Deposit Amt)|(Credit[\\s]*\\(INR\\)[\\s]*Balance)|(Credit\$)|(Deposit Amount)|(Deposits)|(DEPOSITS)|(Deposit)|(CR)|(CREDIT)|(Credit[\\s]*Amount)|(DEPOSIT)|(Cr[\\s]*Amount)")
        headerMap.put("debit", "(Withdrawal[\\s]*Amt.)|(DEBITS)|(Debit Amt)|(Withdrawl Amt)|(Debit[\\s]*\\(INR\\)[\\s]*Balance)|(Debit)|(Withdrawal Amount)|(Withdrawals)|(WITHDRAWALS)|(Withdrawal\$)|(WITHDRAWLS)|(DR)|(DEBIT)|(WithDrawal)|(Debit[\\s]*Amount)|(WITHDRAWAL)|(Dr[\\s]*Amount)")
        headerMap.put("amount_type", "(CR/DR)|(Cr/D[\\s]*r)|(DR/CR)|(Debit\\/)|(DR[|]CR)")
        headerMap.put("amount", "(Withdrawal Deposit \\(Cr\\) \\(Dr\\)\\/)|(Transaction[\\s]*Amount)|(Withdrawal[\\s]*\\(Dr\\)\\/)|(Trxn Amount)|(Amount[\\s]*\\(INR\\))|(Transaction\$)|(Amount\\(in Rs.\\))|(^Amount)")
        headerMap.put("balance_brought_forward", "(B/F[\\s]*[.]{3})|(Balance Brought Forward)|(^B/F\$)|(B/f)|(Opening Balance)|(Brought[\\s]*Forward)|(BALANCE[\\s]*FORWARD)|(BALANCE[\\s]*B/F)|(Balance[\\s]*B/F)")
        headerMap.put("balance_after_transaction", "(Balance[\\s]*Amount)|(Day's[\\s]*Closing)|(Balance[(]IN)|(Closing)|(Running[\\s]*Balance)|(Closing[\\s]*Balance)|(BALANCE AMT)|(^Balance)|(BALANCE)|(Closing Balnace*)|(Available)|(Balance\\(in RS.\\))|(Account[\\s]*Bala([n])?ce)|(Account[\\s]*Balance[\\s]*\\(INR\\))|(Total)")
        headerMap.put("instrument_id", "(Instrument[\\s]*ID)")
        headerMap.put("closing_balance", "(Closing[\\s]*Balance)|(TOTAL)|(Total)")
        headerMap.put("junk_date", "(^TOTAL\$)|(Final Tally)|(Account Total)|(Branch Total)|(Closing Balance)|(Grand Total)")
        headerMap.put("acceptable_date", "(^(0[0-9]|1[1-2]):[0-5][0-9]:[0-5][0-9])")
        return headerMap
    }

    public static SimpleDateFormat findStatementDateFormat(JSONArray jsonArray) {
        Map<String, String> headerMap = headerDictionary()
        JSONObject jsonPageObject = jsonArray.get(0) as JSONObject
        for (int i = 0; i < jsonPageObject.data.length(); i++) {
            for (int j = 0; j < jsonPageObject.data.get(i).length(); j++) {
                String headerName = jsonPageObject.data.get(i).get(j).name
                String headerValue = processValue(jsonPageObject.data.get(i).get(j).value)
                log.debug(headerName)
                log.debug(headerValue)
                if ((headerName.find(headerMap.date) || headerName.find(headerMap.value_date)) && headerValue != null && headerValue.find(DATE_REGEX)) {
                    return dateFormatFromString(headerValue)
                }
            }
        }
    }

    public static SimpleDateFormat dateFormatFromString(String date) {
        if (date.find("([0-3]?[0-9] [A-z]{3,4} [0-9]{4})")) {
            return new SimpleDateFormat("dd MMM yyyy")
        } else if (date.find("[0-3]?[0-9]/[0-1]?[0-9]/[0-9]{4}")) {
            return new SimpleDateFormat("dd/MM/yyyy")
        } else if (date.find("[0-3][0-9]-[0-1][0-9]-[0-9]{4}")) {
            return new SimpleDateFormat("dd-MM-yyyy")
        } else if (date.find("[0-3][0-9]/[0-1][0-9]/[0-9]{2}")) {
            return new SimpleDateFormat("dd/MM/yy")
        } else if (date.find("([0-3]?[0-9]-[\\s]*[A-z]{3,4}-[\\s]*[0-9]{2,4})")) {
            return new SimpleDateFormat("dd-MMM-yyyy")
        }
//        else if (date.find("([0-3]?[0-9]-[A-z]{3,4}-[0-9]{2,4})")) {
//            return new SimpleDateFormat("yyyy-MM-dd")
//        }
        else if (date.find("([0-9]{4}-[0-1][0-9]-[0-3][0-9])")) {
            return new SimpleDateFormat("yyyy-MM-dd")
        } else if (date.find("[0-1]?[0-9]/[0-3]?[0-9]/[0-9]{4}")) {
            return new SimpleDateFormat("MM/dd/yyyy")
        } else if (date.find("[0-1]?[0-9]-[0-3]?[0-9]-[0-9]{4}")) {
            return new SimpleDateFormat("MM-dd-yyyy")
        } else if (date.find("[0-1]?[0-9] [A-z]{3} '[0-9]{2}")) {
            return new SimpleDateFormat("dd MMM ''yy")
        } else if (date.find("[0-3]?[0-9]-[0-1]?[0-9]-[0-9]{2}")) {
            return new SimpleDateFormat("dd-MM-yy")
        } else if (date.find("([0-3]?[0-9] [A-z]{3,4} [0-9]{2})")) {
            return new SimpleDateFormat("dd MMM yy")
        }
    }

    public static String findStatementDateRegex(JSONArray jsonArray) {
        Map<String, String> headerMap = headerDictionary()
        JSONObject jsonPageObject = jsonArray.get(0) as JSONObject
        for (int i = 0; i < jsonPageObject.data.length(); i++) {
            for (int j = 0; j < jsonPageObject.data.get(i).length(); j++) {
                String headerName = jsonPageObject.data.get(i).get(j).name
                String headerValue = processValue(jsonPageObject.data.get(i).get(j).value)
                if ((headerName.find(headerMap.date) || headerName.find(headerMap.value_date)) && headerValue != null && headerValue.find(DATE_REGEX)) {
                    return dateRegexFromString(headerValue)
                }
            }

