            it.transactionCategory in [BankTransactionCategory.SALARY, BankTransactionCategory.INTEREST] || it.transactionSubcategory == BankTransactionSubcategory.SALARY
        }
        salaryTransactions.each { transaction ->
            Boolean isSalaryCheck = publicHolidaysService.checkPublicHoliday(transaction.transactionDate)
            incomeVOList << new IncomeVO(transaction, isSalaryCheck)
        }
        incomeVOList
    }

    public List<IncomeVO> fetchSalaryInstances(List<BankTransactionResponse> transactionList) {
        List<IncomeVO> incomeVOList = []
        List<BankTransactionResponse> salaryTransactions = transactionList.findAll {
            it.transactionCategory == BankTransactionCategory.SALARY || it.transactionSubcategory == BankTransactionSubcategory.SALARY
        }
        salaryTransactions.each { transaction ->
            Boolean isSalaryCheck = publicHolidaysService.checkPublicHoliday(transaction.transactionDate)
            incomeVOList << new IncomeVO(transaction, isSalaryCheck)
        }
        incomeVOList
    }

    public List<IncomeVO> fetchIncomePerMonth(List<BankTransactionResponse> transactionList) {
        List<IncomeVO> monthWiseIncomeVOList = []
        List<IncomeVO> incomeVOList = fetchIncomeInstances(transactionList).sort { it.date }
        if (incomeVOList) {
            List<Date> monthRangeList = DateUtil.getDatesOfMonthsBetweenTwoDates(incomeVOList.first().date, incomeVOList.last().date)
            monthRangeList.each { Date currentDate ->
                Long totalIncomeOfCurrentMonth = incomeVOList.findAll {
                    it.date > DateUtil.getFirstDayOfMonth(currentDate) && it.date <= DateUtil.getLastDayOfMonth(currentDate)
                }*.amount.sum()
                if (totalIncomeOfCurrentMonth) {
                    monthWiseIncomeVOList << new IncomeVO(amount: totalIncomeOfCurrentMonth, date: DateUtil.getLastDayOfMonth(currentDate), description: "Income of ${DateUtil.getLastDayOfMonth(currentDate).format(' MMM yyyy')}")
                }
            }
        }
        monthWiseIncomeVOList
    }

    public Double fetchAverageIncomePerMonth(List<BankTransactionResponse> transactionList) {
        Double avgIncome = 0.00
        List<IncomeVO> incomeVOList = fetchIncomeInstances(transactionList).sort { it.date }
        if (incomeVOList) {
            List<Date> noOfMonths = DateUtil.getDatesOfMonthsBetweenTwoDates(incomeVOList.first().date, incomeVOList.last().date)
            println "**** No of Months between the date range for Income : ${noOfMonths.size()}"
            Double totalIncome = incomeVOList*.amount.sum()
            if (totalIncome) {
                avgIncome = totalIncome / noOfMonths.size()
                println " ==== Total Income : ${totalIncome} and Average Income : ${avgIncome}"
            }
        }
        return avgIncome
    }

