import java.text.SimpleDateFormat
import java.util.regex.Matcher
import java.util.regex.Pattern

class BankTransactionUtil {

    private static final log = LogFactory.getLog(this)
    private static
    final String DATE_REGEX = "(^[0-3]?[0-9][-|/|\\s*][A-z]{3,4}[-|/|\\s*][0-9]{2,4}\$)|(^[0-3]?[0-9][-|/|\\s*][0-1]?[0-9][-|/|\\s*][0-9]{2,4}\$)|(^[0-3]?[0-9][-|/|\\s*][0-1][0-9][-|/|\\s*][0-9]{2,4} [0-9]{2}:[0-9]{2}\$)"

//    Month names as printed by the banks. 'JUY' is a well known OCR mistake for 'JUL' and 'SEPT' is a longer
//    variant of 'SEP'. Both are normalized to the three letter form understood by SimpleDateFormat.
    public static final String MONTH_NAME_REGEX = "JAN|FEB|MAR|APR|MAY|JUN|JUL|JUY|AUG|SEP|SEPT|OCT|NOV|DEC"
    public static final Map<String, String> MONTH_NAME_CORRECTION_MAP = ["JUY": "JUL", "SEPT": "SEP"]
//    Month name dates printed by the banks may be separated by spaces, by hyphens/slashes or not separated at all
//    ('01 JAN 2016', '01-JAN-2016', '01JAN2016'). The pattern below recognizes all of those spellings.
    private static
    final Pattern MONTH_NAME_DATE_PATTERN = Pattern.compile("^([0-3]?[0-9])[\\s]*([-/]?)[\\s]*(${MONTH_NAME_REGEX})[\\s]*([-/]?)[\\s]*([0-9]{4}|[0-9]{2})\$", Pattern.CASE_INSENSITIVE)

//    Rows repeating the column titles in the middle of a statement, e.g. 'Date Particulars Withdrawals Balance'
    private static final String HEADER_ROW_REGEX = "^[^0-9]+\$"

    /**
     * Normalizes a month name date so that every spelling used by the supported banks ends up in a single,
     * consistently separated form. Spaces, hyphens/slashes and completely missing separators are all accepted and
     * the known 'JUY' OCR error for July (as well as the longer 'SEPT') is corrected.
     *
     * '01JAN2016', '01 JAN 2016', '01 - JAN - 2016' and '01-JUY-16' become '01 JAN 2016', '01 JAN 2016',
     * '01-JAN-2016' and '01-JUL-16' respectively. Anything that is not a month name date is returned untouched.
     */
    public static String normalizeMonthNameDateString(String dateString) {
        if (!dateString) {
            return dateString
        }
        String normalized = dateString.trim()
        Matcher matcher = MONTH_NAME_DATE_PATTERN.matcher(normalized)
        if (!matcher.matches()) {
            return normalized
        }
        String day = matcher.group(1)
        String month = matcher.group(3).toUpperCase()
        String year = matcher.group(5)
        month = MONTH_NAME_CORRECTION_MAP.containsKey(month) ? MONTH_NAME_CORRECTION_MAP.get(month) : month
        String separator = matcher.group(2) ?: matcher.group(4) ?: " "
        "${day}${separator}${month}${separator}${year}".toString()
    }

    /**
     * Null/range safe access to a cell of a transaction row. The header of a statement does not always contain
     * every column the parsers know about, hence the column index may legitimately be null.
     */
    public static String getCellText(Elements rowElements, Integer index) {
        if (index == null || rowElements == null || index < 0 || index >= rowElements.size()) {
            return ""
        }
        rowElements.eq(index).text() ?: ""
    }

    /**
     * True when the given description cell holds an opening balance / balance brought forward marker instead of a
     * real transaction narration.
     */
    public static Boolean isOpeningBalanceDescription(String description) {
        if (!description || !description.trim()) {
            return Boolean.FALSE
        }
        String trimmedDescription = description.trim()
        Boolean result = trimmedDescription.find(headerDictionary().balance_brought_forward) ||
                trimmedDescription.find("(?i)^[\\s]*(opening[\\s]*balance|b[\\s]*/[\\s]*f|bal[\\s]*b/f|balance[\\s]*(brought[\\s]*)?forward)")
        result ? Boolean.TRUE : Boolean.FALSE
    }

    /**
     * True when the given row repeats the transaction table header instead of holding a transaction. Statements
     * spanning several pages print the column titles again on every page.
     */
    public static Boolean isTransactionHeaderRow(Elements rowElements, BankTransactionHeaderIndex headerIndex) {
        if (!rowElements || !headerIndex) {
            return Boolean.FALSE
        }
        Map<String, String> headerMap = headerDictionary()
        String dateCell = getCellText(rowElements, headerIndex.transactionDateIndex).trim()
        String valueDateCell = getCellText(rowElements, headerIndex.valueDateIndex).trim()
        String descriptionCell = getCellText(rowElements, headerIndex.descriptionIndex).trim()
        if (dateCell && dateCell.find(HEADER_ROW_REGEX) && dateCell.find(headerMap.date)) {
            return Boolean.TRUE
        }
        if (!dateCell && valueDateCell && valueDateCell.find(HEADER_ROW_REGEX) && valueDateCell.find(headerMap.value_date)) {
            return Boolean.TRUE
        }
        if (!dateCell && descriptionCell && descriptionCell.find(HEADER_ROW_REGEX) && descriptionCell.find(headerMap.description)) {
            return Boolean.TRUE
        }
        Boolean.FALSE
    }

    /**
     * Resolves the transaction date of a row. A continuation row carrying a running balance but no date of its own
     * belongs to the day of the transaction printed above it, so the date is inherited instead of dropping the row.
     */
    public static Date resolveTransactionDate(String dateString, ProcessedBankStatementVO processedBankStatementVO) {
        String date = processValue(dateString ? dateString.trim() : "")
        if (date) {
            try {
                SimpleDateFormat dateFormat = dateFormatFromString(date)
                if (dateFormat) {
                    return dateFormat.parse(date)
                }
            } catch (Exception e) {
                log.debug("Unable to parse the transaction date '${date}'. Falling back to the previous transaction date.")
            }
        }
        processedBankStatementVO?.bankTransactionList ? processedBankStatementVO.bankTransactionList.last().transactionDate : null
    }

    public static SimpleDateFormat dateFormatFromString(String date) {
        if (!date) {
            return null
        }
        date = normalizeMonthNameDateString(date)
        if (date.find("([0-3]?[0-9] [A-z]{3,4} [0-9]{4})")) {
            return new SimpleDateFormat("dd MMM yyyy")
