    public
    static void extractTransactionsFromHTMLHavingDescriptionAboveAndBelowDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            if (!elements || elements.empty) {
                continue
            }
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (getCellText(elements.first().select("td"), bankTransactionHeaderIndex.transactionDateIndex).find("[A-z]{4,}")) {
                elements.remove(0)
            }
            Integer elementCount = elements.size()
            Integer lineCount = 0
            String date = ""
            String description = ""
            Boolean afterDateDescription = false
            while (lineCount < elementCount) {
                try {
                    Elements rowElements = elements.get(lineCount).select("td")
                    String dateCell = getCellText(rowElements, bankTransactionHeaderIndex.transactionDateIndex).trim()
                    String descriptionCell = getCellText(rowElements, bankTransactionHeaderIndex.descriptionIndex)
//                    Repeated column titles and opening balance markers are not transactions.
                    if (isTransactionHeaderRow(rowElements, bankTransactionHeaderIndex) || isOpeningBalanceDescription(descriptionCell)) {
                        description = ""
                        afterDateDescription = false
                        lineCount += 1
                        continue
                    }
                    if (dateCell) {
                        BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                        date = processValue(dateCell)
                        bankTransactionResponse.transactionDate = resolveTransactionDate(date, processedBankStatementVO)
                        description = description + " " + descriptionCell
                        if (afterDateDescription && lineCount + 1 < elementCount && !getCellText(elements.get(lineCount + 1).select("td"), bankTransactionHeaderIndex.transactionDateIndex).trim()) {
                            description = description + " " + getCellText(elements.get(lineCount + 1).select("td"), bankTransactionHeaderIndex.descriptionIndex)
                            afterDateDescription = false
                            ++lineCount
                        }
                        bankTransactionResponse.description = description
                        bankTransactionResponse.remark = getCellText(rowElements, bankTransactionHeaderIndex.chequeNoIndex)
                        bankTransactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(getCellText(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex))
                        if (bankTransactionHeaderIndex.debitIndex && getCellText(rowElements, bankTransactionHeaderIndex.debitIndex)) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(getCellText(rowElements, bankTransactionHeaderIndex.debitIndex))
                            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
                        }
                        if (bankTransactionHeaderIndex.creditIndex && getCellText(rowElements, bankTransactionHeaderIndex.creditIndex) &&
                                (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(getCellText(rowElements, bankTransactionHeaderIndex.creditIndex))
                            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
                        }
                        if (bankTransactionHeaderIndex.amountIndex && getCellText(rowElements, bankTransactionHeaderIndex.amountIndex)) {
                            bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(getCellText(rowElements, bankTransactionHeaderIndex.amountIndex))
                        }
                        if (bankTransactionHeaderIndex.amountTypeIndex && getCellText(rowElements, bankTransactionHeaderIndex.amountTypeIndex)) {
                            if (getCellText(rowElements, bankTransactionHeaderIndex.amountTypeIndex).toLowerCase().find("cr"))
                                bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
                            else
                                bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
                        }
                        processedBankStatementVO.bankTransactionList << bankTransactionResponse
                        description = ""
                        afterDateDescription = false
                    } else {
                        description = descriptionCell
                        afterDateDescription = true
                    }
                } catch (Exception e) {
                    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                    processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                    processedBankStatementVO.statementStatus.message = "Exception occurred during parsing ${processedBankStatementVO.processBankStatementCO.bank} download statement 'HTMLHavingDescriptionAboveAndBelowDate' ====>>>>>> ${e.message}"
                    log.error(processedBankStatementVO.statementStatus.message, e)
                }
                lineCount += 1
            }
        }
        BankUtil.checkForOpeningBalanceTransaction(processedBankStatementVO.bankTransactionList,
                processedBankStatementVO.basicDetails?.fromDate?.getTime())
        BankUtil.findFromAndToDate(processedBankStatementVO.bankTransactionList.first(),
                processedBankStatementVO.bankTransactionList.last(), processedBankStatementVO.basicDetails)
        BankUtil.addCreditOrDebitAndBalanceForTransaction(processedBankStatementVO)
    }

