package com.bankScraper.bank

import com.bankScraper.*
import com.bankScraper.category.TransactionCategory
import org.apache.commons.lang.StringUtils

class BankTransactionResponse implements Serializable {

    private static final long serialVersionUID = 1L;
    String transactionNumber
    Date transactionDate
    Date valueDate
    String description
    Enums.BankTransactionType type
    Double amount
    BigDecimal balanceAfterTransaction
    String remark
    BankTransactionCategory transactionCategory = BankTransactionCategory.PROCESSING
    BankTransactionSubcategory transactionSubcategory
    String firstLevelTransactionCategoryUID = TransactionCategory.fetchOtherCategoryUID(TransactionCategoryConstant.TransactionCategoryLevel.FIRST)
    String secondLevelTransactionCategoryUID = TransactionCategory.fetchOtherCategoryUID(TransactionCategoryConstant.TransactionCategoryLevel.SECOND)
    String transactionId        //TODO
    String matchedClientKeyword
    String uniqueId = AppUtil.uniqueStr
    String bankAccountUID
    Boolean isInternalPayment = Boolean.FALSE
    Boolean isRepetitive = Boolean.FALSE
    Integer serialNo
    Integer fileIndex
    Enums.TransactionDataType chequeType = Enums.TransactionDataType.ORDINARY
    String categoryAlias
    String categoryNumbers

    BankTransactionResponse() {}

    BankTransactionResponse(BankTransaction bankTransaction) {
        this.transactionDate = bankTransaction.dateTime
        this.valueDate = bankTransaction.valueDate
        this.description = bankTransaction.description
        this.type = bankTransaction.type
        this.amount = bankTransaction.amount
        this.balanceAfterTransaction = bankTransaction.balanceAfterTransaction
        this.remark = bankTransaction.remark
        this.transactionCategory = bankTransaction.transactionCategory
        this.transactionSubcategory = bankTransaction.transactionSubcategory
        this.transactionId = bankTransaction.transactionID
        this.matchedClientKeyword =<REDACTED>
        this.uniqueId = bankTransaction.uniqueId
        this.isInternalPayment = bankTransaction.isInternalPayment
        this.bankAccountUID = bankTransaction.bankAccountUID
        this.chequeType = bankTransaction.chequeType
    }

    BankTransactionResponse(def bankTransactionMap) {
        this.transactionDate = HelperMethod.stringToDate(bankTransactionMap.transactionDate)
        if (bankTransactionMap.valueDate)
            this.valueDate = HelperMethod.stringToDate(bankTransactionMap.valueDate)
        this.description = bankTransactionMap.description
        this.type = bankTransactionMap.type
        this.amount = Double.valueOf(bankTransactionMap.amount)
        this.balanceAfterTransaction = Double.valueOf(bankTransactionMap.balanceAfterTransaction)
        this.remark = bankTransactionMap.remark
        if (bankTransactionMap.transactionNumber && bankTransactionMap.transactionNumber != "null")
            this.transactionNumber = bankTransactionMap.transactionNumber
        this.transactionCategory = BankTransactionCategory.valueOf(bankTransactionMap.transactionCategory)
        if (bankTransactionMap.transactionSubcategory && bankTransactionMap.transactionSubcategory != "null")
            this.transactionSubcategory = BankTransactionSubcategory.valueOf(bankTransactionMap.transactionSubcategory)
        this.transactionId = bankTransactionMap.transactionID
        this.isInternalPayment = bankTransactionMap.isInternalPayment && bankTransactionMap.isInternalPayment.equals("true")
        this.uniqueId = bankTransactionMap.uniqueId
        this.bankAccountUID = bankTransactionMap.bankAccountUID
        this.matchedClientKeyword =<REDACTED>
        this.firstLevelTransactionCategoryUID = bankTransactionMap.firstLevelTransactionCategoryUID
        this.secondLevelTransactionCategoryUID = bankTransactionMap.secondLevelTransactionCategoryUID
        this.categoryAlias = bankTransactionMap.categoryAlias
        this.categoryNumbers = bankTransactionMap.categoryNumbers
        if (bankTransactionMap.chequeType && bankTransactionMap.chequeType != "null") {
            this.chequeType = Enums.TransactionDataType.valueOf(bankTransactionMap.chequeType)
        } else {
            this.chequeType = Enums.TransactionDataType.ORDINARY
        }
    }

    String getRemarkShortText() {
        StringUtils.isBlank(this.remark) ? '-' : this.remark.length() > 13 ? this.remark.substring(0, 13) + '...' : this.remark
    }

    String getDescriptionShortText() {
        this.description && this.description.length() > 60 ? this.description.substring(0, 60) + '...' : this.description
    }

    BankAccount getBankAccount() {
        BankAccount bankAccount = BankAccount.createCriteria().get {
            eq('uniqueId', this.bankAccountUID)
        }
        //TODO: assigning it to "" so to prevent BankAccount having whole transaction JSON data over and over again
        bankAccount?.bankTransactionData = ""
        bankAccount
    }

    BigDecimal getBalanceAfterTransaction() {
        HelperMethod.roundTo2Places(this.balanceAfterTransaction)
    }

    TransactionCategory fetchFirstLevelTransactionCategory() {
        TransactionCategory.findByUniqueId(this.firstLevelTransactionCategoryUID)
    }

    TransactionCategory fetchSecondLevelTransactionCategory() {
        TransactionCategory.findByUniqueId(this.secondLevelTransactionCategoryUID)
    }

//    TODO: new categorisation
    Boolean isOpeningBalanceTransaction() {
        if (this.transactionCategory.equals(BankTransactionCategory.OPENING_BALANCE)) {
            return true
        } else if (this.fetchFirstLevelTransactionCategory()?.name?.equals(TransactionCategoryConstant.BankTransactionCategoryConstant.OPENING_BALANCE.value)) {
            return true
        } else if (this.description?.toLowerCase()?.equals("opening balance")) {
            return true
        } else {
            return false
        }
    }

    Boolean isOnlineShoppingTransaction() {
        if (this.transactionSubcategory == BankTransactionSubcategory.E_COMMERCE) {
            return true
        } else if (this.secondLevelTransactionCategoryUID.equals(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.ONLINE_SHOPPING.value, TransactionCategoryConstant.TransactionCategoryLevel.SECOND))) {
            return true
        } else {
            return false
        }
    }

    Boolean isMobileBillTransaction() {
        if (this.transactionSubcategory == BankTransactionSubcategory.MOBILE_BILL) {
            return true
        } else if (this.secondLevelTransactionCategoryUID.equals(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.MOBILE_BILL.value, TransactionCategoryConstant.TransactionCategoryLevel.SECOND))) {
            return true
        } else {
            return false
        }
    }

    Boolean isEntertainmentTransaction() {
        if (this.transactionSubcategory == BankTransactionSubcategory.ENTERTAINMENT) {
            return true
        } else if (this.secondLevelTransactionCategoryUID.equals(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.ENTERTAINMENT.value, TransactionCategoryConstant.TransactionCategoryLevel.SECOND))) {
            return true
        } else {
            return false
        }
    }

    Boolean isSalaryIncomeTransaction() {
        this.secondLevelTransactionCategoryUID.equals(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.SALARY.value, TransactionCategoryConstant.BankTransactionCategoryConstant.SALARY.level))
    }

    Boolean isSalaryTransaction() {
        this.secondLevelTransactionCategoryUID in [(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.SALARY.value, TransactionCategoryConstant.BankTransactionCategoryConstant.SALARY.level)),
                                                   (TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.EMPLOYEE_SALARY.value, TransactionCategoryConstant.BankTransactionCategoryConstant.EMPLOYEE_SALARY.level))]
    }

    Boolean isExpenseTransaction() {
        this.fetchSecondLevelTransactionCategory().name in [TransactionCategoryConstant.BankTransactionCategoryConstant.ENTERTAINMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.FOOD_AND_RESTAURANT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.TRAVEL.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.ONLINE_SHOPPING.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.MOBILE_BILL.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.FUEL.value
        ]
    }

    Boolean isInvestmentTransaction() {
        this.fetchSecondLevelTransactionCategory().name in [TransactionCategoryConstant.BankTransactionCategoryConstant.INVESTMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.EQUITY_INVESTMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.FIXED_DEPOSIT_INVESTMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.MUTUAL_FUND_INVESTMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.RECURRING_DEPOSIT_INVESTMENT.value,
                                                            TransactionCategoryConstant.BankTransactionCategoryConstant.SIP_INVESTMENT.value
        ]
    }

    Boolean isCashDepositTransaction() {
        this.firstLevelTransactionCategoryUID.equals(TransactionCategory.fetchCategoryUID(TransactionCategoryConstant.BankTransactionCategoryConstant.CASH_DEPOSIT.value, TransactionCategoryConstant.BankTransactionCategoryConstant.CASH_DEPOSIT.level))
    }

    Boolean isWithdrawalTransaction() {
