class HelperMethod {
    static Double getSanitizeDouble(String value) {
        if (!value) {
            return 0d
        }
        String sanitized = value.replaceAll("[^0-9.\\-]", "")
        if (!sanitized || !sanitized.find("[0-9]")) {
            return 0d
        }
        try {
            return Double.parseDouble(sanitized)
        } catch (Exception e) {
            return 0d
        }
    }

    static BigDecimal roundTo2Places(def value) {
        value == null ? null : new BigDecimal(value.toString()).setScale(2, BigDecimal.ROUND_HALF_UP)
    }
}

