/**
 * True when the given row repeats the transaction table header instead of holding a transaction. Statements
 * spanning several pages print the column titles again on every page. A row is only considered a header when at
 * least two of its cells hold the title of the column they sit in and none of them holds a digit, so that a
 * narration that happens to contain a word like 'Details' is never mistaken for a header.
 */
public static Boolean isTransactionHeaderRow(Elements rowElements, BankTransactionHeaderIndex headerIndex) {
    if (!rowElements || !headerIndex) {
        return Boolean.FALSE
    }
    Map<String, String> headerMap = headerDictionary()
    Map<Integer, String> columnTitleMap = [:]
    columnTitleMap.put(headerIndex.transactionDateIndex, headerMap.date)
    columnTitleMap.put(headerIndex.valueDateIndex, headerMap.value_date)
    columnTitleMap.put(headerIndex.descriptionIndex, headerMap.description)
    columnTitleMap.put(headerIndex.chequeNoIndex, headerMap.cheque_no)
    columnTitleMap.put(headerIndex.debitIndex, headerMap.debit)
    columnTitleMap.put(headerIndex.creditIndex, headerMap.credit)
    columnTitleMap.put(headerIndex.amountIndex, headerMap.amount)
    columnTitleMap.put(headerIndex.balanceAfterTransactionIndex, headerMap.balance_after_transaction)
    columnTitleMap.remove(null)
    Integer matchedTitleCount = 0
    for (columnIndex in columnTitleMap.keySet()) {
        String cell = getCellText(rowElements, columnIndex).trim()
        if (!cell) {
            continue
        }
        if (!cell.find(HEADER_ROW_REGEX) || !cell.find(columnTitleMap.get(columnIndex))) {
            return Boolean.FALSE
        }
        matchedTitleCount++
    }
    matchedTitleCount >= 2 ? Boolean.TRUE : Boolean.FALSE
}

