    }
    if (!dateCell && valueDateCell && valueDateCell.find(HEADER_ROW_REGEX) && valueDateCell.find(headerMap.value_date)) {
        return Boolean.TRUE
    }
    if (!dateCell && descriptionCell && descriptionCell.find(HEADER_ROW_REGEX) && descriptionCell.find(headerMap.description)) {
        return Boolean.TRUE
    }
    Boolean.FALSE
}

